window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bb729648276e9cc2"]={"versions": [{"id": "FIG-bb729648276e9cc2", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm / Metamodell-Ausschnitt zur Spezifikation der BSW-Parameterkonfiguration (gemäß AUTOSAR BSW Template / ECU Configuration Specification). Es definiert die hierarchische Konfigurationsstruktur für Hardware-Filtermasken des CAN-Treibers (<code>Can</code>) auf Controller-Ebene und dient als formale Vorgabe für Konfigurationswerkzeuge (ECU Configuration Editors / Code-Generatoren).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>CanController</code> (<code>:ParamConfContainerDef</code>): Übergeordneter Konfigurationscontainer für einen CAN-Controller mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>.\n</li><li><code>+subContainer</code>: Kompositionsbeziehung vom Controller zu untergeordneten Containern.\n</li><li><code>CanFilterMask</code> (<code>:ParamConfContainerDef</code>): Konfigurationscontainer für eine Hardware-Filtermaske mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>.\n</li><li><code>+parameter</code>: Kompositionsbeziehung zur Einbettung von Konfigurationsparametern in den Container.\n</li><li><code>CanFilterMaskValue</code> (<code>:IntegerParamDef</code>): Ganzzahliger Konfigurationsparameter, der den numerischen Bitmaskenwert zur CAN-Identifier-Filterung spezifiziert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell bildet das Diagramm keinen sequenziellen Laufzeitablauf ab. Zur Konfigurationszeit instanziiert das BSW-Werkzeug für jeden konfigurierten CAN-Controller (<code>CanController</code>) null bis beliebig viele Filtermasken-Container (<code>CanFilterMask</code>) mit jeweils einem ganzzahligen Filtermaskenwert (<code>CanFilterMaskValue</code>). Zur Initialisierungszeit wertet der CAN-Treiber (typischerweise in <code>Can_Init()</code>) die generierten Maskenstrukturen aus und programmiert die Hardware-Filterregister der CAN-Controller entsprechend.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich ist die Festlegung der Kardinalitäten: Mindestens ein <code>CanController</code> muss definiert werden (<code>1..*</code>), während <code>CanFilterMask</code> optional ist (<code>0..*</code>), womit Controller ohne dedizierte Filtermasken zulässig sind. BSW-Entwickler und Modulkonfiguratoren müssen beachten, dass <code>CanFilterMaskValue</code> bitgenau auf das Hardware-Layout der Filterregister (Standard-/Extended-ID-Bits, Maskierung) des Ziel-Controllers abgebildet werden muss und die Masken konsistent zu den zugehörigen Hardware-Objekten (<code>CanHardwareObject</code>) zu konfigurieren sind.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-bce0f5799f51a6c5", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm / Metamodell-Ausschnitt zur Spezifikation der BSW-Parameterkonfiguration (gemäß AUTOSAR BSW Template / ECU Configuration Specification). Es definiert die hierarchische Konfigurationsstruktur für Hardware-Filtermasken des CAN-Treibers (<code>Can</code>) auf Controller-Ebene und dient als formale Vorgabe für Konfigurationswerkzeuge (ECU Configuration Editors / Code-Generatoren).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>CanController</code> (<code>:ParamConfContainerDef</code>): Übergeordneter Konfigurationscontainer für einen CAN-Controller mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>.\n</li><li><code>+subContainer</code>: Kompositionsbeziehung vom Controller zu untergeordneten Containern.\n</li><li><code>CanFilterMask</code> (<code>:ParamConfContainerDef</code>): Konfigurationscontainer für eine Hardware-Filtermaske mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>.\n</li><li><code>+parameter</code>: Kompositionsbeziehung zur Einbettung von Konfigurationsparametern in den Container.\n</li><li><code>CanFilterMaskValue</code> (<code>:IntegerParamDef</code>): Ganzzahliger Konfigurationsparameter, der den numerischen Bitmaskenwert zur CAN-Identifier-Filterung spezifiziert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell bildet das Diagramm keinen sequenziellen Laufzeitablauf ab. Zur Konfigurationszeit instanziiert das BSW-Werkzeug für jeden konfigurierten CAN-Controller (<code>CanController</code>) null bis beliebig viele Filtermasken-Container (<code>CanFilterMask</code>) mit jeweils einem ganzzahligen Filtermaskenwert (<code>CanFilterMaskValue</code>). Zur Initialisierungszeit wertet der CAN-Treiber (typischerweise in <code>Can_Init()</code>) die generierten Maskenstrukturen aus und programmiert die Hardware-Filterregister der CAN-Controller entsprechend.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich ist die Festlegung der Kardinalitäten: Mindestens ein <code>CanController</code> muss definiert werden (<code>1..*</code>), während <code>CanFilterMask</code> optional ist (<code>0..*</code>), womit Controller ohne dedizierte Filtermasken zulässig sind. BSW-Entwickler und Modulkonfiguratoren müssen beachten, dass <code>CanFilterMaskValue</code> bitgenau auf das Hardware-Layout der Filterregister (Standard-/Extended-ID-Bits, Maskierung) des Ziel-Controllers abgebildet werden muss und die Masken konsistent zu den zugehörigen Hardware-Objekten (<code>CanHardwareObject</code>) zu konfigurieren sind.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-bb729648276e9cc2", "to": "FIG-bce0f5799f51a6c5", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Diagrammrahmen: Der äußere UML-Rahmen (<code>object CanFilterMask</code>) wurde entfernt.\n</li><li><code>CanController</code> &amp; <code>CanFilterMask</code>: Die Reihenfolge der Attribute im unteren Kompartiment wurde vertauscht (<code>upperMultiplicity</code> steht nun vor <code>lowerMultiplicity</code>; Wertebereiche <code>1..*</code> bzw. <code>0..*</code> sind unverändert).\n</li><li>Darstellungsstil: Die Schlagschatten aller Modellelement-Boxen wurden entfernt.\n</li></ul>"}]};
